<?php
require 'config/functions.php';require 'config/database.php';$q=trim($_GET['q']??'');$status=$_GET['status']??'';$sql='SELECT r.*,h.household_code FROM residents r LEFT JOIN households h ON h.id=r.household_id WHERE 1=1';$p=[];
if($q!==''){$sql.=' AND (r.first_name LIKE ? OR r.middle_name LIKE ? OR r.last_name LIKE ? OR r.address LIKE ? OR r.email LIKE ?)';$v="%$q%";array_push($p,$v,$v,$v,$v,$v);}if(in_array($status,['Active','Inactive','Moved','Deceased'],true)){$sql.=' AND r.status=?';$p[]=$status;}$sql.=' ORDER BY r.last_name,r.first_name';$s=$pdo->prepare($sql);$s->execute($p);$rows=$s->fetchAll();start_page('Residents');
?>
<div class="pagehead"><div class="wrap"><h1>Resident Information</h1><p class="muted">Search residents, filter by status, and update records.</p></div></div><main class="wrap"><div class="panel"><?php show_flash();?><div class="toolbar no-print"><form method="get"><input class="search" name="q" placeholder="Search name, address, email" value="<?=e($q)?>"><select class="search" name="status" style="width:auto"><option value="">All statuses</option><?php foreach(['Active','Inactive','Moved','Deceased'] as $x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button class="btn primary">Search</button><a class="btn" style="background:#edf1f7" href="residents.php">Reset</a></form><a class="btn primary" href="resident_form.php">+ Add Resident</a></div><p class="muted"><?=count($rows)?> record(s) found.</p><div class="tablewrap"><table><thead><tr><th>Name</th><th>Address</th><th>Household</th><th>Status</th><th class="no-print">Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5">No resident records found.</td></tr><?php endif;foreach($rows as $r):?><tr><td><?=e(trim($r['first_name'].' '.$r['middle_name'].' '.$r['last_name']))?></td><td><?=e($r['address'])?></td><td><?=e($r['household_code']??'Not assigned')?></td><td><span class="badge <?=$r['status']!=='Active'?'inactive':''?>"><?=e($r['status'])?></span></td><td class="no-print"><a href="resident_form.php?id=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div></div></main><?php end_page();?>
